<script lang="ts">import CorrelationWorkspaceControls from './CorrelationWorkspaceControls.svelte';import type {CorrelationWorkspaceView} from '../correlation-workspace-chrome-presentation.js';let {view}:{view:CorrelationWorkspaceView}=$props();const nativeImageRole="img" as const;</script><svelte:options preserveWhitespace={true}/><CorrelationWorkspaceControls view={view.controls}/>{#each view.notices as notice}<div class="corr-dose-notice"><span><strong>{notice.name}</strong> · {notice.message}</span>{#if notice.confirmation!==null}<details class="corr-confirm-dose"><summary>Confirm dose dates</summary><p>Use {notice.confirmation.dose} for this period only if unchanged.</p>{#each notice.confirmation.periods as period}<div><span>{period.start} → {period.end}</span><button type="button" class="corr-review-dose" data-corr-confirm-dose="{period.id}" data-corr-period="{period.index}">Confirm &amp; save this period</button></div>{/each}<p class="corr-confirm-status" role="status"></p></details>{/if}<button type="button" class="corr-review-dose" data-compare-action="review-therapy" data-compare-key="{notice.id}">{notice.reviewLabel}</button></div>{/each}
<div id="corr-workspace-plots" hidden={view.plotsHidden}>{#if view.panels.length}{#each view.panels as panel}<section class="corr-timeline-panel{panel.classSuffix}"><h4 class={panel.headingHidden ? 'sr-only' : undefined}>{panel.heading}</h4>{#if panel.plot!==null}<p class="corr-scale-label">{panel.plot.scaleLabel}</p><div class="corr-dose-chart{panel.plot.classSuffix}"><canvas id="corr-workspace-chart-{panel.plot.index}" role={nativeImageRole} aria-label="{panel.plot.name} over calendar time"></canvas></div>{/if}{#each panel.tracks as track}<div class="corr-use-timeline" data-corr-track="{track.id}"><div class="corr-use-heading">{track.name} · Recorded use <span>Not a dose scale</span></div><div class="corr-use-track"></div></div>{/each}</section>{/each}{:else}<p>Turn on a series above.</p>{/if}</div>
<div class="corr-inspector" hidden={view.inspectorHidden}><div class="corr-date-heading"><strong>Values on <time id="corr-inspect-label">{view.inspectLabel}</time></strong><button type="button" id="corr-unpin" class="corr-review-dose" hidden={view.unpinHidden}>Unpin date</button><details class="corr-jump"><summary>Jump to date</summary><label class="sr-only" for="corr-inspect">Jump to date</label><input type="date" id="corr-inspect" value="{view.inspectValue}" min="{view.inspectMin}" max="{view.inspectMax}"></details></div><div id="corr-readout" aria-live="polite"></div></div>
<details class="corr-method" hidden={view.methodHidden}><summary>How to read this chart</summary><p>Hover to preview; click to pin a date. Lines join lab results; steps show dated doses. Gaps mean unknown; dose zero means a break or off-day. Relative scales run from each series’ minimum (0) to maximum (100), not health thresholds; constant values sit at 50. Analysis uses raw values, including hidden series.</p></details>
<details class="corr-analysis-disclosure" data-analysis-tab="{view.analysisTab}" open={view.analysisOpen}><summary>Statistics &amp; data</summary>
<div class="corr-pair-analysis">{#if view.pairTabs!==null}<div class="corr-pair-tabs" role="tablist" aria-label="Comparison">{#each view.pairTabs.items as pair}<button type="button" role="tab" id="corr-pair-{pair.index}" data-corr-pair="{pair.actionIndex}" aria-selected={pair.selected} aria-controls="corr-analysis-panel" tabindex={pair.tabindex}>{pair.marker} × {pair.therapy}</button>{/each}</div>{/if}
<div id="corr-analysis-panel" {...(view.panel ?? {})}>
<p class="corr-help">{view.pairSummary}</p>
{#if view.scatterUnavailable!==null}<p role="status">Scatter unavailable: dose units, bases or ingredients differ.</p>{/if}
<div class="corr-dose-chart" hidden={view.scatterHidden}><canvas id="corr-scatter" role={nativeImageRole} aria-label="Paired observations; excluded rows are not plotted"></canvas></div>
<div id="corr-pair-detail"></div>
</div></div>
</details>
{#if view.history!==null}<details class="corr-history"><summary>Current doses</summary><div class="corr-current-references">{#each view.history.items as dose}<section class="corr-current-dose"><div class="corr-current-heading"><strong>{dose.name}</strong><button type="button" class="corr-review-dose" data-compare-action="review-therapy" data-compare-key="{dose.id}">Edit dose history</button></div>{#if dose.doses.kind==='current-dose-list'}<ul>{#each dose.doses.items as item}<li><span>{item.ingredient}</span><span><strong>{item.amount}</strong><small>{item.since}</small></span></li>{/each}</ul>{:else}<p>No daily amount saved.</p>{/if}</section>{/each}</div></details>{/if}